import json
from pathlib import Path


def обійти(вузол, шлях):
    if isinstance(вузол, dict):
        for ключ, значення in vузол.items():
            yield from обійти(значення, шлях + [str(ключ)])
    elif isinstance(вузол, list):
        for індекс, значення in enumerate(вузол):
            yield from обійти(значення, шлях + [str(індекс)])
    elif isinstance(вузол, (int, float)) and not isinstance(вузол, bool):
        if вузол > 100:
            yield ".".join(шлях), вузол


def main():
    with open(Path("дані") / "структура.json", encoding="utf-8") as f:
        дані = json.load(f)

    знайдено = 0
    for шлях, значення in обійти(дані, []):
        print(f"{шлях} = {значення}")
        знайдено += 1

    print(f"Знайдено: {знайдено}")


if __name__ == "__main__":
    main()

